<script setup>
import {ref,watch,onMounted,onBeforeUnmount,computed,defineAsyncComponent} from 'vue';
import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {receiverPreviewFrame,createReceiverPreviewGroup,disposeReceiverPreviewGroup,fitReceiverPreviewCamera} from './receiver-preview-scene.js';
import {nativeTriangleForHit,validateNativePreviewScene,highlightNativeElement,isolateNativeElement,nativePreviewHit,fitNativeSelectionCamera} from './native-preview-scene.js';
import {verifyNativeMeasurements,MAX_NATIVE_MEASUREMENT_REPORT_BYTES} from '../shared/native-measurement-verifier.mjs';
import {nativeMeasurementReport,nativeMeasurementsCsv} from '../shared/native-measurement-export.mjs';
import {nativeElementMetrics} from '../shared/native-element-metrics.mjs';
import {traceNativeTriangle} from '../shared/native-resource-budget.mjs';
const NativeMeasurementComparison=defineAsyncComponent(()=>import('./NativeMeasurementComparison.vue')),comparisonOpen=ref(false);
const props=defineProps({sceneData:{type:Object,required:true},manifest:{type:Object,required:true},archiveIdentity:{type:Object,required:true},triangle:{type:Number,required:true}}),emit=defineEmits(['close','select']);
const viewport=ref(null),closeButton=ref(null),error=ref(''),ready=ref(false),ceilings=ref(false),wireframe=ref(false),isolated=ref(false),visibleCount=ref(0),framing=ref('scene'),exportScope=ref('selected'),exportMessage=ref(''),verificationMessage=ref(''),verification=ref(null),verifying=ref(false);let verificationGeneration=0;
const selected=computed(()=>{try{return traceNativeTriangle(props.manifest,props.triangle);}catch{return null;}});
const measurements=computed(()=>{if(!selected.value)return null;try{return {value:nativeElementMetrics(props.sceneData,props.manifest,selected.value.elementId)};}catch(cause){return {error:cause.message};}});
const measure=value=>new Intl.NumberFormat('en',{maximumFractionDigits:4}).format(Object.is(value,-0)?0:value);
let renderer,camera,scene,controls,group,observer,frame,disposed=false,previousFocus,pointerStart;
function highlight(){if(group){highlightNativeElement(group,selected.value?.elementId);visibleCount.value=isolateNativeElement(group,selected.value?.elementId,isolated.value);}}
function rebuild(){if(!scene)return;if(group){scene.remove(group);disposeReceiverPreviewGroup(group);}group=createReceiverPreviewGroup(props.sceneData,{ceilings:ceilings.value||selected.value?.kind==='ceiling',wireframe:wireframe.value});scene.add(group);highlight();}
function fit(selection=false){if(!camera||!group)return;const r=viewport.value.getBoundingClientRect(),aspect=Math.max(1,r.width)/Math.max(1,r.height),damping=controls.enableDamping;controls.enableDamping=false;controls.update();let target=new THREE.Vector3();if(selection&&selected.value){target=fitNativeSelectionCamera(camera,group,selected.value.elementId,aspect).centre;framing.value='selection';}else{fitReceiverPreviewCamera(camera,receiverPreviewFrame(props.sceneData).span,aspect);framing.value='scene';}controls.target.copy(target);controls.update();controls.enableDamping=damping;}

function exportMeasurements(format){try{if(exportScope.value==='selected'&&!selected.value)throw Error('Choose a source element to export');const report=nativeMeasurementReport(props.sceneData,props.manifest,props.archiveIdentity,exportScope.value==='all'?null:selected.value?.elementId),content=format==='csv'?nativeMeasurementsCsv(report):JSON.stringify(report,null,2)+'\n',url=URL.createObjectURL(new Blob([content],{type:format==='csv'?'text/csv;charset=utf-8':'application/json'})),link=document.createElement('a');link.href=url;link.download='terratec-native-measurements-'+exportScope.value+'.'+format;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);exportMessage.value='Exported '+report.elements.length+' source elements as '+format.toUpperCase()+'.';}catch(cause){exportMessage.value=cause.message;}}
async function verifyMeasurements(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;const generation=++verificationGeneration;verification.value=null;verificationMessage.value='';verifying.value=true;try{if(file.size>MAX_NATIVE_MEASUREMENT_REPORT_BYTES)throw Error('Measurement report exceeds 16 MiB');const result=verifyNativeMeasurements(await file.text(),{scene:props.sceneData,manifest:props.manifest,identity:props.archiveIdentity});if(disposed||generation!==verificationGeneration)return;verification.value=result;verificationMessage.value='Verified '+result.format.toUpperCase()+' measurement report against this ZIP: '+result.elements+' elements ('+result.scope+'). Internal consistency only; author identity is not verified.';}catch(cause){if(!disposed&&generation===verificationGeneration)verificationMessage.value=cause.message;}finally{if(!disposed&&generation===verificationGeneration)verifying.value=false;}}
function choose(event){const entry=props.manifest.elements.find(e=>e.elementId===event.target.value);if(entry)emit('select',entry.firstTriangle);}
function pick(event){if(!pointerStart||Math.hypot(event.clientX-pointerStart.x,event.clientY-pointerStart.y)>5){pointerStart=null;return;}pointerStart=null;if(!group||!camera)return;const r=renderer.domElement.getBoundingClientRect();const hit=nativePreviewHit(group,camera,new THREE.Vector2((event.clientX-r.left)/r.width*2-1,-(event.clientY-r.top)/r.height*2+1));if(hit)emit('select',nativeTriangleForHit(props.manifest,hit.object.userData.id,hit.faceIndex));}
function down(event){pointerStart=event.button===0?{x:event.clientX,y:event.clientY}:null;}
watch(exportScope,()=>{exportMessage.value='';});watch([ceilings,wireframe],rebuild);watch(isolated,()=>{highlight();if(isolated.value&&selected.value)fit(true);});watch(()=>props.triangle,()=>{exportMessage.value='';if(group?.children.some(m=>m.userData.kind==='ceiling')!==(ceilings.value||selected.value?.kind==='ceiling'))rebuild();else highlight();if(framing.value==='selection')fit(Boolean(selected.value));});
onMounted(()=>{previousFocus=document.activeElement;closeButton.value?.focus();try{
 validateNativePreviewScene(props.sceneData,props.manifest);renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.domElement.setAttribute('aria-label','Native source geometry canvas');viewport.value.appendChild(renderer.domElement);renderer.domElement.addEventListener('pointerdown',down);renderer.domElement.addEventListener('pointerup',pick);
 scene=new THREE.Scene();scene.background=new THREE.Color(0xe6ece4);scene.add(new THREE.HemisphereLight(0xffffff,0x596b60,2));const sun=new THREE.DirectionalLight(0xffffff,2);sun.position.set(4,8,5);scene.add(sun);camera=new THREE.PerspectiveCamera(45,1,.01,1000);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;rebuild();fit();observer=new ResizeObserver(()=>{if(disposed)return;const r=viewport.value.getBoundingClientRect();renderer.setSize(Math.max(1,r.width),Math.max(1,r.height));camera.aspect=Math.max(1,r.width)/Math.max(1,r.height);camera.updateProjectionMatrix();fit(framing.value==='selection');});observer.observe(viewport.value);const animate=()=>{if(disposed)return;controls.update();renderer.render(scene,camera);frame=requestAnimationFrame(animate);};animate();ready.value=true;
 }catch(cause){error.value='Native source preview unavailable: '+cause.message;}});
onBeforeUnmount(()=>{disposed=true;verificationGeneration++;cancelAnimationFrame(frame);observer?.disconnect();controls?.dispose();renderer?.domElement.removeEventListener('pointerdown',down);renderer?.domElement.removeEventListener('pointerup',pick);disposeReceiverPreviewGroup(group);renderer?.dispose();renderer?.forceContextLoss();renderer?.domElement.remove();if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true});});
</script>
<template><section class="native-source-preview" role="dialog" aria-label="Native source geometry preview" aria-modal="false" @keydown.stop @keydown.esc.prevent="emit('close')"><header><h3>Native source geometry preview</h3><button ref="closeButton" @click="emit('close')">Close native source preview</button></header><p>Verified bundle geometry · browser preview · click to select, drag to orbit, wheel to zoom. Selection highlights the complete source element. Selecting a ceiling reveals it while selected. Native engine picking and live physics remain disconnected.</p><div><label>Native preview source element<select aria-label="Native preview source element" :value="selected?.elementId??''" @change="choose"><option v-if="!selected" value="" disabled>Choose an element</option><option v-for="entry in manifest.elements" :key="entry.elementId" :value="entry.elementId">{{ entry.roomId }} · {{ entry.kind }} · {{ entry.wallId??entry.furnitureId??'' }}</option></select></label><button :disabled="!ready" @click="fit(false)">Fit native source geometry</button><button :disabled="!ready||!selected" @click="fit(true)">Fit selected native element</button><label><input v-model="isolated" :disabled="!ready||!selected" type="checkbox">Isolate selected native element</label><label><input v-model="ceilings" type="checkbox">Show native preview ceilings</label><label><input v-model="wireframe" type="checkbox">Native preview wireframe</label></div><p v-if="ready" data-testid="native-preview-ready">Preview ready: {{ manifest.summary.triangles }} triangles</p><p v-if="ready" data-testid="native-preview-view">{{ visibleCount }} visible elements · {{ framing==='selection'?'Selection framed':'Whole scene framed' }} · {{ isolated?'Isolation on':'Isolation off' }}</p><p v-if="error" role="alert">{{ error }}</p><p data-testid="native-preview-selection" role="status">{{ selected?JSON.stringify(selected):'Choose a valid triangle or source element.' }}</p><div v-if="ready"><label>Native measurement export scope<select v-model="exportScope" aria-label="Native measurement export scope"><option value="selected">Selected element</option><option value="all">All bundle elements (including hidden)</option></select></label><button :disabled="exportScope==='selected'&&!selected" @click="exportMeasurements('json')">Export native measurements JSON</button><button :disabled="exportScope==='selected'&&!selected" @click="exportMeasurements('csv')">Export native measurements CSV</button><label>Verify native measurement report<input :disabled="verifying" type="file" accept=".json,.csv,application/json,text/csv" @change="verifyMeasurements"></label><p data-testid="native-measurement-verification" role="status">{{ verificationMessage }}</p><p v-if="verification" data-testid="native-measurement-verification-summary">{{ verification.scope }} · {{ verification.elements }} elements · {{ verification.archiveSha256 }}</p><p data-testid="native-measurement-export-message" role="status">{{ exportMessage }}</p></div><div v-if="ready"><button :aria-expanded="comparisonOpen" @click="comparisonOpen=!comparisonOpen">Compare native measurements</button><NativeMeasurementComparison v-if="comparisonOpen" :scene-data="sceneData" :manifest="manifest" :archive-identity="archiveIdentity"/></div><details v-if="measurements" class="native-measurements" open><summary>Selected source measurements</summary><p v-if="measurements.error" role="alert">{{ measurements.error }}</p><div v-else data-testid="native-element-measurements"><p>Project-local Y-up metres · axis-aligned spans<span v-if="measurements.value.approximation"> · furniture bounding-box approximation</span><span v-else> · zero-thickness surface</span></p><table aria-label="Selected native element bounds"><thead><tr><th>Axis</th><th>Minimum (m)</th><th>Maximum (m)</th><th>Span (m)</th></tr></thead><tbody><tr v-for="axis in ['x','y','z']" :key="axis"><th>{{ axis.toUpperCase() }}</th><td>{{ measure(measurements.value.bounds.min[axis]) }}</td><td>{{ measure(measurements.value.bounds.max[axis]) }}</td><td>{{ measure(measurements.value.axisAlignedSpans[axis]) }}</td></tr></tbody></table><p data-testid="native-element-area">Triangulated {{ measurements.value.approximation?'bounds ':'' }}area: {{ measure(measurements.value.triangulatedArea) }} m²</p><p>Centre (m): {{ ['x','y','z'].map(axis=>measure(measurements.value.centre[axis])).join(', ') }} · Triangle range: [{{ measurements.value.triangleRange.first }}, {{ measurements.value.triangleRange.endExclusive }}) · {{ measurements.value.triangleRange.count }} triangles</p><p>Spans describe world-axis extents, not nominal dimensions of rotated furniture. Areas exclude wall openings; bounds areas do not describe cabinet internals. No volume, mass or physical properties are inferred.</p></div></details><div ref="viewport" class="native-source-canvas"></div></section></template>
<style>
.native-source-preview{position:fixed;inset:4vh 4vw;z-index:210;display:flex;flex-direction:column;padding:16px;gap:8px;background:#edf1e8;color:#263e3c;box-shadow:0 8px 50px #0007;overflow:auto}.native-source-preview header{display:flex;justify-content:space-between;gap:12px;align-items:center}.native-source-preview h3,.native-source-preview p{margin:2px 0}.native-source-preview p{font-size:12px;overflow-wrap:anywhere}.native-source-preview label{display:inline-flex;align-items:center;gap:4px;margin-right:8px;font-size:12px}.native-measurements{font-size:12px;max-height:26vh;overflow:auto}.native-measurements table{border-collapse:collapse;width:100%;max-width:540px}.native-measurements th,.native-measurements td{padding:3px 8px;border:1px solid #a3b6ad;text-align:right}.native-measurements summary{cursor:pointer}.native-source-canvas{flex:1;min-height:220px;overflow:hidden}.native-source-canvas canvas{display:block;width:100%;height:100%;touch-action:none}
</style>
